INSERT INTO `{prefix}_index_detail` (`id`, `module_id`, `language`, `topic`, `description`, `detail`, `keywords`) VALUES (1, 1, '', 'หน้าหลัก', '{SITE_NAME} ร้านค้าออนไลน์ของใช้ ของแต่งบ้าน แฟชั่น และของฝาก คัดสรรคุณภาพ จัดส่งทั่วประเทศ', '<h2>ยินดีต้อนรับสู่ {SITE_NAME}</h2><p>เราคัดสรรของใช้ในชีวิตประจำวัน ของแต่งบ้าน และของฝากจากผู้ผลิตท้องถิ่น <strong>คุณภาพดี ราคายุติธรรม</strong> สั่งง่าย ชำระเงินได้หลายช่องทาง และจัดส่งทั่วประเทศ</p><ul><li><a href="{WEBURL}product">สินค้าทั้งหมด</a> — เลือกชมตามหมวดหมู่ ขนาด และสี</li><li><a href="{WEBURL}news">โปรโมชัน</a> — ส่วนลดและกิจกรรมพิเศษประจำเดือน</li><li><a href="{WEBURL}howto">วิธีสั่งซื้อ</a> — ขั้นตอนสั่งซื้อ ชำระเงิน และติดตามพัสดุ</li></ul><p><em>สินค้าและราคาทั้งหมดเป็นข้อมูลตัวอย่าง แก้ไขได้ที่หน้าผู้ดูแล</em></p>', 'ร้านค้าออนไลน์,ของใช้,ของแต่งบ้าน,ของฝาก,{SITE_NAME}');
INSERT INTO `{prefix}_index_detail` (`id`, `module_id`, `language`, `topic`, `description`, `detail`, `keywords`) VALUES (2, 2, '', 'สินค้าทั้งหมด', 'สินค้าของใช้ ของแต่งบ้าน แฟชั่น อาหาร และอุปกรณ์ไอทีจาก{SITE_NAME}', '<p>เลือกซื้อสินค้าได้ตามหมวดหมู่ สินค้าที่มีตัวเลือกให้เลือกขนาดหรือสีได้ในหน้าสินค้า</p>', 'สินค้า,ร้านค้าออนไลน์,ของใช้,แฟชั่น');
INSERT INTO `{prefix}_index_detail` (`id`, `module_id`, `language`, `topic`, `description`, `detail`, `keywords`) VALUES (3, 3, '', 'ข่าวสารและโปรโมชัน', 'โปรโมชัน ส่วนลด สินค้าใหม่ และข่าวสารจาก{SITE_NAME}', '<p>โปรโมชันและข่าวสารล่าสุดของร้าน</p>', 'โปรโมชัน,ส่วนลด,สินค้าใหม่');
INSERT INTO `{prefix}_index_detail` (`id`, `module_id`, `language`, `topic`, `description`, `detail`, `keywords`) VALUES (4, 4, '', 'ถาม-ตอบสินค้า', 'สอบถามข้อมูลสินค้า การสั่งซื้อ และการจัดส่งกับ{SITE_NAME}', '', 'ถาม-ตอบ,สอบถามสินค้า,การจัดส่ง');
INSERT INTO `{prefix}_index_detail` (`id`, `module_id`, `language`, `topic`, `description`, `detail`, `keywords`) VALUES (5, 5, '', 'แกลเลอรี่', 'ภาพหน้าร้าน กิจกรรม และภาพสินค้าจากลูกค้าของ{SITE_NAME}', '', 'แกลเลอรี่,ภาพสินค้า,หน้าร้าน');
INSERT INTO `{prefix}_index_detail` (`id`, `module_id`, `language`, `topic`, `description`, `detail`, `keywords`) VALUES (6, 6, '', 'วิดีโอรีวิวสินค้า', 'วิดีโอรีวิวและแนะนำวิธีใช้สินค้า', '', 'วิดีโอ,รีวิวสินค้า,YouTube');
INSERT INTO `{prefix}_index_detail` (`id`, `module_id`, `language`, `topic`, `description`, `detail`, `keywords`) VALUES (7, 7, '', 'เกี่ยวกับร้าน', 'เรื่องราวและความตั้งใจของ{SITE_NAME}', '<h2>เรื่องราวของเรา</h2><p>{SITE_NAME} เริ่มจากความชอบของใช้ที่ดีไซน์เรียบง่ายแต่ใช้งานได้จริง เราคัดสินค้าทุกชิ้นด้วยตัวเอง และทำงานร่วมกับผู้ผลิตท้องถิ่นเพื่อให้ลูกค้าได้สินค้าคุณภาพในราคายุติธรรม</p><h2>สิ่งที่เรายึดถือ</h2><ul><li><strong>คุณภาพก่อนราคา</strong> — ทดลองใช้ก่อนนำมาขายทุกชิ้น</li><li><strong>สนับสนุนชุมชน</strong> — รายได้ส่วนหนึ่งกลับสู่ผู้ผลิตท้องถิ่น</li><li><strong>บริการจริงใจ</strong> — เปลี่ยนคืนได้ภายใน 7 วัน</li></ul><table><tbody><tr><th>ลูกค้า</th><td>12,000+ ราย</td></tr><tr><th>สินค้า</th><td>300+ รายการ</td></tr><tr><th>คะแนนรีวิว</th><td>4.9 / 5</td></tr></tbody></table>', 'เกี่ยวกับร้าน,เรื่องราว');
INSERT INTO `{prefix}_index_detail` (`id`, `module_id`, `language`, `topic`, `description`, `detail`, `keywords`) VALUES (8, 8, '', 'วิธีสั่งซื้อ', 'ขั้นตอนการสั่งซื้อ ชำระเงิน จัดส่ง และการเปลี่ยนคืนสินค้า', '<h2>ขั้นตอนการสั่งซื้อ</h2><ol><li>เลือกสินค้าและตัวเลือก (ขนาด/สี) แล้วกด <strong>หยิบใส่ตะกร้า</strong></li><li>ตรวจสอบตะกร้าแล้วกด <strong>สั่งซื้อ</strong></li><li>กรอกชื่อ ที่อยู่จัดส่ง และเลือกวิธีจัดส่ง</li><li>เลือกวิธีชำระเงิน โอนเงินผ่านธนาคาร หรือเก็บเงินปลายทาง</li><li>โอนเงินแล้วแจ้งชำระเงินพร้อมแนบสลิปที่หน้า <strong>คำสั่งซื้อของฉัน</strong></li></ol><h2>ค่าจัดส่ง</h2><table><thead><tr><th>วิธีจัดส่ง</th><th>ค่าบริการ</th><th>ระยะเวลา</th></tr></thead><tbody><tr><td>ไปรษณีย์ลงทะเบียน</td><td>50 บาท (ฟรีเมื่อซื้อครบ 1,000 บาท)</td><td>2-4 วัน</td></tr><tr><td>ขนส่งด่วนเอกชน</td><td>40 บาท + 15 บาท/กก.</td><td>1-2 วัน</td></tr><tr><td>รับสินค้าที่ร้าน</td><td>ฟรี</td><td>พร้อมรับภายใน 1 วัน</td></tr></tbody></table><h2>ตารางขนาดเสื้อยืด</h2><table><thead><tr><th>ขนาด</th><th>รอบอก (นิ้ว)</th><th>ความยาว (นิ้ว)</th></tr></thead><tbody><tr><td>S</td><td>38</td><td>27</td></tr><tr><td>M</td><td>40</td><td>28</td></tr><tr><td>L</td><td>42</td><td>29</td></tr><tr><td>XL</td><td>44</td><td>30</td></tr></tbody></table><h2>การเปลี่ยนคืนสินค้า</h2><p>เปลี่ยนหรือคืนสินค้าได้ภายใน 7 วันหลังได้รับสินค้า สินค้าต้องอยู่ในสภาพเดิมพร้อมบรรจุภัณฑ์ สอบถามได้ที่ <a href="{WEBURL}forum">ถาม-ตอบสินค้า</a></p>', 'วิธีสั่งซื้อ,ชำระเงิน,จัดส่ง,เปลี่ยนคืนสินค้า');
INSERT INTO `{prefix}_index_detail` (`id`, `module_id`, `language`, `topic`, `description`, `detail`, `keywords`) VALUES (9, 9, '', 'ติดต่อร้าน', 'ที่อยู่ร้าน เบอร์โทรศัพท์ และช่องทางติดต่อ{SITE_NAME}', '<h2>ติดต่อ {SITE_NAME}</h2><p><strong>หน้าร้าน :</strong> เลขที่ 9 ถนนตัวอย่าง ตำบลตัวอย่าง อำเภอเมือง จังหวัดตัวอย่าง 99999<br><strong>โทรศัพท์ :</strong> 08-0000-0000<br><strong>อีเมล :</strong> {SITE_EMAIL}<br><strong>เวลาเปิดร้าน :</strong> ทุกวัน 10.00 – 19.00 น.</p><p>สอบถามสินค้าออนไลน์ได้ที่ <a href="{WEBURL}forum">ถาม-ตอบสินค้า</a></p><p><em>ข้อมูลติดต่อเป็นตัวอย่าง แก้ไขได้ที่หน้าผู้ดูแล › หน้าเพจ › ติดต่อร้าน</em></p>', 'ติดต่อร้าน,ที่อยู่,โทรศัพท์');
INSERT INTO `{prefix}_index_detail` (`id`, `module_id`, `language`, `topic`, `description`, `detail`, `keywords`) VALUES (10, 3, '', 'ลดทั้งร้าน 10% เมื่อซื้อครบ 1,000 บาท ส่งฟรีทั่วประเทศ', 'ช้อปครบ 1,000 บาท รับส่วนลด 10% และจัดส่งฟรีด้วยไปรษณีย์ลงทะเบียน ตลอดเดือนนี้', '<p>เพียงช้อปสินค้าครบ <strong>1,000 บาท</strong> ต่อคำสั่งซื้อ รับส่วนลด 10% ทันที และจัดส่งฟรีด้วยไปรษณีย์ลงทะเบียน</p><ul><li>ระยะเวลา: ตลอดเดือนนี้</li><li>ใช้ได้กับสินค้าทุกหมวด ยกเว้นสินค้าลดราคาอยู่แล้ว</li><li>จำกัด 1 สิทธิ์ต่อคำสั่งซื้อ</li></ul><p><a href="{WEBURL}product">เลือกซื้อสินค้า</a></p>', 'โปรโมชัน,ส่งฟรี');
INSERT INTO `{prefix}_index_detail` (`id`, `module_id`, `language`, `topic`, `description`, `detail`, `keywords`) VALUES (11, 3, '', 'สินค้าใหม่ เสื้อยืดคอตตอนออร์แกนิก มาแล้ว', 'เสื้อยืดผ้าคอตตอนออร์แกนิก 100% มีให้เลือก 4 ขนาด 2 สี', '<p>เสื้อยืดคอตตอนออร์แกนิก 100% เนื้อผ้านุ่ม ระบายอากาศดี มีให้เลือกขนาด S ถึง XL สีขาวและสีกรมท่า</p><p>ดูรายละเอียดและเลือกขนาดได้ที่ <a href="{WEBURL}product">หน้าสินค้า</a></p>', 'สินค้าใหม่,แฟชั่น');
INSERT INTO `{prefix}_index_detail` (`id`, `module_id`, `language`, `topic`, `description`, `detail`, `keywords`) VALUES (12, 3, '', 'กระเป๋าผ้าสีเขียว ลดเหลือ 299 บาท', 'ราคาพิเศษสำหรับกระเป๋าผ้าแคนวาสสีเขียว จากปกติ 350 บาท', '<p>กระเป๋าผ้าแคนวาสสีเขียว ลดราคาพิเศษเหลือ <strong>299 บาท</strong> จากปกติ 350 บาท จนกว่าสินค้าจะหมด</p>', 'โปรโมชัน,กระเป๋า');
INSERT INTO `{prefix}_index_detail` (`id`, `module_id`, `language`, `topic`, `description`, `detail`, `keywords`) VALUES (13, 3, '', 'ของขวัญปีใหม่ ห่อของขวัญฟรีทุกคำสั่งซื้อ', 'เลือกบริการห่อของขวัญพร้อมการ์ดอวยพรได้ฟรี เพียงระบุในหมายเหตุตอนสั่งซื้อ', '<p>ร้านห่อของขวัญพร้อมการ์ดอวยพรให้ฟรี เพียงพิมพ์ข้อความในช่องหมายเหตุตอนสั่งซื้อ</p>', 'ของขวัญ,โปรโมชัน');
INSERT INTO `{prefix}_index_detail` (`id`, `module_id`, `language`, `topic`, `description`, `detail`, `keywords`) VALUES (14, 3, '', 'สินค้าชุมชน น้ำผึ้งดอกลำไยและกล่องไม้ไผ่', 'สนับสนุนผู้ผลิตท้องถิ่นด้วยสินค้าคุณภาพจากวิสาหกิจชุมชน', '<p>ร้านร่วมกับวิสาหกิจชุมชนนำสินค้าคุณภาพมาจำหน่าย รายได้ส่วนหนึ่งกลับคืนสู่ผู้ผลิตโดยตรง</p>', 'สินค้าชุมชน,ของฝาก');
INSERT INTO `{prefix}_index_detail` (`id`, `module_id`, `language`, `topic`, `description`, `detail`, `keywords`) VALUES (15, 3, '', 'ประกาศวันหยุดจัดส่งสินค้า', 'งดจัดส่งสินค้าในวันหยุดนักขัตฤกษ์ คำสั่งซื้อในช่วงดังกล่าวจัดส่งในวันทำการถัดไป', '<p>ร้านงดจัดส่งสินค้าในวันหยุดนักขัตฤกษ์ คำสั่งซื้อที่เข้ามาในช่วงดังกล่าวจะจัดส่งในวันทำการถัดไปตามลำดับ</p>', 'ประกาศ,การจัดส่ง');
INSERT INTO `{prefix}_index_detail` (`id`, `module_id`, `language`, `topic`, `description`, `detail`, `keywords`) VALUES (16, 3, '', 'รีวิวจากลูกค้า ขวดน้ำสแตนเลสเก็บความเย็นได้ทั้งวัน', 'ลูกค้าเล่าประสบการณ์ใช้ขวดน้ำสแตนเลสระหว่างเดินทางและออกกำลังกาย', '<blockquote>ใส่น้ำแข็งตอนเช้า ตกเย็นยังเหลือน้ำแข็งอยู่เลย พกไปทำงานทุกวัน</blockquote><p>ขอบคุณลูกค้าทุกท่านที่ส่งรีวิวมาให้ร้าน</p>', 'รีวิว,ขวดน้ำ');
INSERT INTO `{prefix}_index_detail` (`id`, `module_id`, `language`, `topic`, `description`, `detail`, `keywords`) VALUES (17, 3, '', 'วิธีดูแลแก้วมัคเซรามิกให้สวยนาน', 'เคล็ดลับทำความสะอาดคราบชากาแฟ และข้อควรระวังในการใช้งาน', '<ol><li>ล้างทันทีหลังใช้งานเพื่อลดคราบ</li><li>ใช้เบกกิ้งโซดาขัดคราบชากาแฟ</li><li>หลีกเลี่ยงการเปลี่ยนอุณหภูมิกะทันหัน</li></ol>', 'เคล็ดลับ,แก้วมัค');
