INSERT INTO `{prefix}_product_detail` (`id`, `module_id`, `language`, `topic`, `keywords`, `description`, `detail`) VALUES (1, 2, 'th', 'แก้วมัคเซรามิก รุ่นคลาสสิก', 'แก้วมัคเซรามิก รุ่นคลาสสิก', 'แก้วมัคเซรามิกเคลือบด้าน จับถนัดมือ เก็บความร้อนได้ดี ขนาด 350 มล.', '<p>แก้วมัคเซรามิกเคลือบด้าน จับถนัดมือ เก็บความร้อนได้ดี ขนาด 350 มล.</p><ul><li>ความจุ 350 มล.</li><li>เข้าไมโครเวฟและเครื่องล้างจานได้</li><li>ผลิตจากเซรามิกปลอดสารตะกั่ว</li></ul>');
INSERT INTO `{prefix}_product_detail` (`id`, `module_id`, `language`, `topic`, `keywords`, `description`, `detail`) VALUES (1, 2, 'en', 'Classic Ceramic Mug', 'Classic Ceramic Mug', 'Matte-glazed 350 ml ceramic mug that keeps drinks hot.', '<p>Matte-glazed 350 ml ceramic mug that keeps drinks hot.</p><ul><li>350 ml capacity</li><li>Microwave and dishwasher safe</li><li>Lead-free ceramic</li></ul>');
INSERT INTO `{prefix}_product_detail` (`id`, `module_id`, `language`, `topic`, `keywords`, `description`, `detail`) VALUES (2, 2, 'th', 'เสื้อยืดคอตตอนออร์แกนิก', 'เสื้อยืดคอตตอนออร์แกนิก', 'เสื้อยืดผ้าคอตตอนออร์แกนิก 100% เนื้อนุ่ม ระบายอากาศดี มีให้เลือก 4 ขนาด 2 สี', '<p>เสื้อยืดผ้าคอตตอนออร์แกนิก 100% เนื้อนุ่ม ระบายอากาศดี มีให้เลือก 4 ขนาด 2 สี</p><ul><li>ผ้าคอตตอนออร์แกนิก 100%</li><li>ทรงตรง ใส่ได้ทั้งชายและหญิง</li><li>ขนาด XL ราคา 420 บาท</li></ul><p>ดูตารางขนาดได้ที่หน้า <a href="{WEBURL}howto">วิธีสั่งซื้อ</a></p>');
INSERT INTO `{prefix}_product_detail` (`id`, `module_id`, `language`, `topic`, `keywords`, `description`, `detail`) VALUES (2, 2, 'en', 'Organic Cotton T-shirt', 'Organic Cotton T-shirt', '100% organic cotton tee, soft and breathable. 4 sizes, 2 colours.', '<p>100% organic cotton tee, soft and breathable. 4 sizes, 2 colours.</p><ul><li>100% organic cotton</li><li>Unisex straight fit</li><li>Size XL costs 420 THB</li></ul>');
INSERT INTO `{prefix}_product_detail` (`id`, `module_id`, `language`, `topic`, `keywords`, `description`, `detail`) VALUES (3, 2, 'th', 'กระเป๋าผ้าแคนวาส', 'กระเป๋าผ้าแคนวาส', 'กระเป๋าผ้าแคนวาสหนา 16 ออนซ์ ใส่ของได้เยอะ มีช่องซิปด้านใน', '<p>กระเป๋าผ้าแคนวาสหนา 16 ออนซ์ ใส่ของได้เยอะ มีช่องซิปด้านใน</p><ul><li>ผ้าแคนวาส 16 ออนซ์</li><li>ขนาด 38 x 40 ซม.</li><li>สีเขียวลดราคาพิเศษ 299 บาท</li></ul>');
INSERT INTO `{prefix}_product_detail` (`id`, `module_id`, `language`, `topic`, `keywords`, `description`, `detail`) VALUES (3, 2, 'en', 'Canvas Tote Bag', 'Canvas Tote Bag', 'Heavy 16 oz canvas tote with an inner zip pocket.', '<p>Heavy 16 oz canvas tote with an inner zip pocket.</p><ul><li>16 oz canvas</li><li>38 x 40 cm</li><li>Green on sale at 299 THB</li></ul>');
INSERT INTO `{prefix}_product_detail` (`id`, `module_id`, `language`, `topic`, `keywords`, `description`, `detail`) VALUES (4, 2, 'th', 'ขวดน้ำสแตนเลสเก็บอุณหภูมิ 500 มล.', 'ขวดน้ำสแตนเลสเก็บอุณหภูมิ 500 มล.', 'ขวดน้ำสแตนเลสสองชั้น เก็บความเย็นได้ 24 ชั่วโมง ความร้อน 12 ชั่วโมง', '<p>ขวดน้ำสแตนเลสสองชั้น เก็บความเย็นได้ 24 ชั่วโมง ความร้อน 12 ชั่วโมง</p><ul><li>สแตนเลส 304 ปลอด BPA</li><li>ความจุ 500 มล.</li><li>ฝาปิดกันรั่ว</li></ul>');
INSERT INTO `{prefix}_product_detail` (`id`, `module_id`, `language`, `topic`, `keywords`, `description`, `detail`) VALUES (4, 2, 'en', 'Insulated Bottle 500 ml', 'Insulated Bottle 500 ml', 'Double-wall stainless bottle: cold for 24 h, hot for 12 h.', '<p>Double-wall stainless bottle: cold for 24 h, hot for 12 h.</p><ul><li>304 stainless steel, BPA free</li><li>500 ml</li><li>Leak-proof lid</li></ul>');
INSERT INTO `{prefix}_product_detail` (`id`, `module_id`, `language`, `topic`, `keywords`, `description`, `detail`) VALUES (5, 2, 'th', 'โคมไฟตั้งโต๊ะมินิมอล', 'โคมไฟตั้งโต๊ะมินิมอล', 'โคมไฟตั้งโต๊ะดีไซน์เรียบ ปรับความสว่างได้ 3 ระดับ เหมาะกับโต๊ะทำงานและหัวเตียง', '<p>โคมไฟตั้งโต๊ะดีไซน์เรียบ ปรับความสว่างได้ 3 ระดับ เหมาะกับโต๊ะทำงานและหัวเตียง</p><ul><li>หลอด LED ประหยัดไฟ</li><li>ปรับแสง 3 ระดับ</li><li>รับประกัน 1 ปี</li></ul>');
INSERT INTO `{prefix}_product_detail` (`id`, `module_id`, `language`, `topic`, `keywords`, `description`, `detail`) VALUES (5, 2, 'en', 'Minimal Desk Lamp', 'Minimal Desk Lamp', 'Clean-lined desk lamp with 3 brightness levels.', '<p>Clean-lined desk lamp with 3 brightness levels.</p><ul><li>Energy-saving LED</li><li>3 brightness levels</li><li>1-year warranty</li></ul>');
INSERT INTO `{prefix}_product_detail` (`id`, `module_id`, `language`, `topic`, `keywords`, `description`, `detail`) VALUES (6, 2, 'th', 'ต้นไม้ฟอกอากาศในกระถางเซรามิก', 'ต้นไม้ฟอกอากาศในกระถางเซรามิก', 'ต้นไม้ฟอกอากาศดูแลง่าย มาพร้อมกระถางเซรามิกสีขาว เหมาะวางในห้องทำงาน', '<p>ต้นไม้ฟอกอากาศดูแลง่าย มาพร้อมกระถางเซรามิกสีขาว เหมาะวางในห้องทำงาน</p><ul><li>สูงประมาณ 35 ซม.</li><li>รดน้ำสัปดาห์ละครั้ง</li><li>แพ็กกันกระแทกอย่างดี</li></ul>');
INSERT INTO `{prefix}_product_detail` (`id`, `module_id`, `language`, `topic`, `keywords`, `description`, `detail`) VALUES (6, 2, 'en', 'Air-purifying Plant', 'Air-purifying Plant', 'Easy-care plant in a white ceramic pot.', '<p>Easy-care plant in a white ceramic pot.</p><ul><li>About 35 cm tall</li><li>Water once a week</li><li>Carefully packed</li></ul>');
INSERT INTO `{prefix}_product_detail` (`id`, `module_id`, `language`, `topic`, `keywords`, `description`, `detail`) VALUES (7, 2, 'th', 'หูฟังไร้สาย รุ่นเบสิก', 'หูฟังไร้สาย รุ่นเบสิก', 'หูฟังไร้สายเสียงใส ใช้งานต่อเนื่อง 6 ชั่วโมง พร้อมกล่องชาร์จ', '<p>หูฟังไร้สายเสียงใส ใช้งานต่อเนื่อง 6 ชั่วโมง พร้อมกล่องชาร์จ</p><ul><li>บลูทูธ 5.3</li><li>ใช้งานต่อเนื่อง 6 ชั่วโมง</li><li>รับประกัน 6 เดือน</li></ul>');
INSERT INTO `{prefix}_product_detail` (`id`, `module_id`, `language`, `topic`, `keywords`, `description`, `detail`) VALUES (7, 2, 'en', 'Wireless Earbuds Basic', 'Wireless Earbuds Basic', 'Clear-sound wireless earbuds, 6 hours playback with charging case.', '<p>Clear-sound wireless earbuds, 6 hours playback with charging case.</p><ul><li>Bluetooth 5.3</li><li>6 h playback</li><li>6-month warranty</li></ul>');
