INSERT INTO `{prefix}_product_detail` (`id`, `module_id`, `language`, `topic`, `keywords`, `description`, `detail`) VALUES (8, 2, 'en', 'Longan Honey 250 g', 'Longan Honey 250 g', 'Pure honey from community longan orchards.', '<p>Pure honey from community longan orchards.</p><ul><li>250 g</li><li>No added syrup</li><li>Community product</li></ul>');
INSERT INTO `{prefix}_product_detail` (`id`, `module_id`, `language`, `topic`, `keywords`, `description`, `detail`) VALUES (9, 2, 'th', 'หมวกแก๊ปผ้าฝ้าย', 'หมวกแก๊ปผ้าฝ้าย', 'หมวกแก๊ปผ้าฝ้ายปรับขนาดได้ด้านหลัง ใส่สบายทุกวัน', '<p>หมวกแก๊ปผ้าฝ้ายปรับขนาดได้ด้านหลัง ใส่สบายทุกวัน</p><ul><li>ผ้าฝ้าย 100%</li><li>สายปรับขนาดด้านหลัง</li></ul>');
