INSERT INTO `{prefix}_product_detail` (`id`, `module_id`, `language`, `topic`, `keywords`, `description`, `detail`) VALUES (10, 2, 'th', 'รองเท้าผ้าใบลำลอง', 'รองเท้าผ้าใบลำลอง', 'รองเท้าผ้าใบน้ำหนักเบา พื้นยางกันลื่น ใส่เดินได้ทั้งวัน', '<p>รองเท้าผ้าใบน้ำหนักเบา พื้นยางกันลื่น ใส่เดินได้ทั้งวัน</p><ul><li>ไซซ์ 39-42</li><li>พื้นยางกันลื่น</li><li>เปลี่ยนไซซ์ได้ภายใน 7 วัน</li></ul>');
