INSERT INTO `{prefix}_product_detail` (`id`, `module_id`, `language`, `topic`, `keywords`, `description`, `detail`) VALUES (16, 2, 'en', 'Dried Flower Tea Gift Box', 'Dried Flower Tea Gift Box', 'Four dried-flower teas in a gift box.', '<p>Four dried-flower teas in a gift box.</p><ul><li>4 flavours x 5 sachets</li><li>Gift boxed</li></ul>');
INSERT INTO `{prefix}_product_detail` (`id`, `module_id`, `language`, `topic`, `keywords`, `description`, `detail`) VALUES (17, 2, 'th', 'นาฬิกาอัจฉริยะ รุ่นสปอร์ต', 'นาฬิกาอัจฉริยะ รุ่นสปอร์ต', 'นาฬิกาอัจฉริยะวัดชีพจร นับก้าว และแจ้งเตือนข้อความ กันน้ำ 5 ATM ลดราคาพิเศษ', '<p>นาฬิกาอัจฉริยะวัดชีพจร นับก้าว และแจ้งเตือนข้อความ กันน้ำ 5 ATM ลดราคาพิเศษ</p><ul><li>หน้าจอสี 1.4 นิ้ว</li><li>แบตเตอรี่ 7 วัน</li><li>กันน้ำ 5 ATM</li></ul>');
INSERT INTO `{prefix}_product_detail` (`id`, `module_id`, `language`, `topic`, `keywords`, `description`, `detail`) VALUES (17, 2, 'en', 'Smart Watch Sport', 'Smart Watch Sport', 'Heart rate, steps and notifications, 5 ATM water resistant. On sale.', '<p>Heart rate, steps and notifications, 5 ATM water resistant. On sale.</p><ul><li>1.4-inch colour display</li><li>7-day battery</li><li>5 ATM</li></ul>');
INSERT INTO `{prefix}_product_detail` (`id`, `module_id`, `language`, `topic`, `keywords`, `description`, `detail`) VALUES (18, 2, 'th', 'หูฟังครอบหู รุ่นโปร', 'หูฟังครอบหู รุ่นโปร', 'หูฟังครอบหูตัดเสียงรบกวน เสียงเบสแน่น ใส่สบายตลอดวัน', '<p>หูฟังครอบหูตัดเสียงรบกวน เสียงเบสแน่น ใส่สบายตลอดวัน</p><ul><li>ตัดเสียงรบกวนแบบแอกทีฟ</li><li>ใช้งานต่อเนื่อง 30 ชั่วโมง</li><li>รับประกัน 1 ปี</li></ul>');
INSERT INTO `{prefix}_product_detail` (`id`, `module_id`, `language`, `topic`, `keywords`, `description`, `detail`) VALUES (18, 2, 'en', 'Over-ear Headphones Pro', 'Over-ear Headphones Pro', 'Noise-cancelling over-ear headphones with rich bass.', '<p>Noise-cancelling over-ear headphones with rich bass.</p><ul><li>Active noise cancelling</li><li>30 h playback</li><li>1-year warranty</li></ul>');
